export function init(root) {
    if (!root || typeof root.appendChild !== "function")
        throw new TypeError("init(root): root must be an Element");
    if (root.querySelector('[data-state="skeleton"]')) return;   // idempotent
    const shell = document.createElement("div");
    shell.dataset.state = "skeleton";
    shell.setAttribute("aria-busy", "true");
    root.appendChild(shell);
}

// Browser only.  Keeps the module importable from node:test without side effects.
if (typeof document !== "undefined") {
    document.addEventListener("DOMContentLoaded", () => {
        const root = document.getElementById("app");
        if (root) init(root);
    });
}

// tests/js/main.test.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { init } from "../../game/static/game/js/main.js";

test("init is exported as a function", () => {
    assert.equal(typeof init, "function");
});

test("init rejects a non-element root", () => {
    assert.throws(() => init(null), TypeError);
    assert.throws(() => init({}), TypeError);
});

test("importing the entry module has no side effects in node", () => {
    assert.equal(typeof globalThis.document, "undefined");
});

