// dim=9 전용 좌표 테이블. server의 spec.py 포팅이 아니다 (DV-04).
const ROW_OF = i => (i / 9) | 0, COL_OF = i => i % 9;
const BOX_OF = i => ((ROW_OF(i) / 3) | 0) * 3 + ((COL_OF(i) / 3) | 0);
PEERS[i] = unique union of row(i), col(i), box(i) members, minus i        // 20 entries
UNITS    = 9 rows ++ 9 cols ++ 9 boxes                                    // 27 entries
freeze everything before export

function effective(values, givens, i) { return givens[i] || values[i]; }

conflicts(values, givens):
    out = new Set()
    for unit of UNITS:
        seen = Map<digit, index[]>
        for i of unit: v = effective(values, givens, i); if v: seen[v].push(i)
        for entries with length > 1: add every index to out
    return out

isSolved(values, givens):
    for unit of UNITS:
        mask = 0
        for i of unit: v = effective(...); if !v return false; mask |= 1 << (v-1)
        if mask !== 0b111111111 return false
    return true

eliminationTargets(candidates, index, digit):
    bit = 1 << (digit - 1)
    return PEERS[index].filter(p => candidates[p] & bit)

mb:micro.mb:output-type:
SerializedSession = {
  schemaVersion: 1, puzzleId: string, dim: 9,
  givens: number[81], values: number[81], candidates: number[81],
  cellNotes: Record<string,string>, regionNotes: Record<string,string>,
  createdAt: number, updatedAt: number
}

mb:micro.mb:pseudocode:
deserializeSession(raw):
    try { obj = JSON.parse(raw) } catch { return fail("corrupt") }
    if (!Number.isInteger(obj?.schemaVersion)) return fail("corrupt")
    if (obj.schemaVersion > CURRENT) return fail("future-version")
    if (obj.schemaVersion < CURRENT) { obj = migrate(obj); if (!obj) return fail("corrupt") }
    run every check above, failing closed on the first violation
    return {ok:true, session: {..., givens:new Uint8Array(obj.givens), ...}}

const STEPS = new Map();          // from version -> fn(obj) -> obj ; empty today
migrate(obj):
    let cur = obj;
    while (cur.schemaVersion < CURRENT) {
        const step = STEPS.get(cur.schemaVersion);
        if (!step) return null;                    // fail closed, never guess
        cur = step(cur);
    }
    return cur;

KEY = "sudoku:v1:session"
schedule(session):
    pending = session
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => { timer = null; write(pending) }, 300)
flushNow():
    if (timer) { clearTimeout(timer); timer = null }
    if (pending) write(pending)
write(session):
    if (mode === "memory") return
    try { storage.setItem(KEY, JSON.stringify(serializeSession(session))); pending = null }
    catch (e) { mode = "memory"; onWarning("storage-unavailable") }   // once, by construction
restore(): raw = storage.getItem(KEY); return raw ? deserializeSession(raw) : {ok:false, code:"empty"}

mb:micro.mb:input-type:
project(session: GameSession, scope: "SC1"|"SC2"|"SC3", savedAt: number|null) -> CanonicalState
CanonicalState = {
  givens: Uint8Array(81),
  values: Uint8Array(81) | null,
  candidates: Uint16Array(81) | null,
  notes: Array<{kind: 0|1|2|3, key: number, text: string}> | null,
  savedAt: number | null
}
checkInvariants(state: CanonicalState) -> {ok:true} | {ok:false, code:"invalid-puzzle"|"malformed-body"}

mb:micro.mb:pseudocode:
KIND = {cell:0, row:1, column:2, box:3}
project(session, scope, savedAt):
    givens = copy(session.givens)
    if (scope === "SC1") return {givens, values:null, candidates:null, notes:null, savedAt:null}
    values = copy(session.values); candidates = copy(session.candidates)
    for i in 0..80: if (givens[i]) { values[i] = 0; candidates[i] = 0 }
                    else if (values[i]) candidates[i] = 0
    notes = scope === "SC3" ? collectNotes(session).sort(byKindThenKey) : null
    return {givens, values, candidates, notes, savedAt}

checkInvariants(state): run every rule above; givens contradiction -> "invalid-puzzle"

writeBody(state):
    flags = (values?1:0) | (candidates?2:0) | (notes?4:0) | (savedAt!=null?8:0)
    out = [flags, 9]
    if (savedAt != null) push 4 bytes little-endian of savedAt
    pushNibbles(out, state.givens)                 // 41 bytes, last nibble zero
    if (values) pushNibbles(out, state.values)
    if (candidates) {
        bitmap = 11 zero bytes; for i where candidates[i]: bitmap bit i = 1   // LSB-first
        push bitmap
        bitWriter = LSB-first writer
        for i in cell order where candidates[i]: bitWriter.write9(candidates[i])
        bitWriter.flush()                          // pads the final byte with zeros
    }
    if (notes) { encodeULEB128(notes.length, out)
                 for n of notes: out.push(n.kind, n.key)
                                 utf8 = encodeUTF8(n.text)
                                 encodeULEB128(utf8.length, out); push utf8 }
    return Uint8Array.from(out)

encode(session, scope, savedAt, deps):
    state = project(session, scope, savedAt)
    body  = writeBody(state)
    crc   = crc32(body)
    packed = await tryDeflateRaw(body, deps)            // null when unsupported
    usePacked = packed && packed.length < body.length
    out = [1, usePacked ? 1 : 0, ...(usePacked ? packed : body), ...le32(crc)]
    return base64urlNoPad(out)

decode(fragment, deps):
    length and alphabet checks
    bytes = base64urlDecode(fragment)
    if (bytes.length < 6) return fail("malformed-body")
    if (bytes[0] !== 1) return fail("unsupported-version")
    codec = bytes[1]; if (codec > 1) return fail("unsupported-codec")
    payload = bytes.slice(2, -4); trailer = le32At(bytes, bytes.length-4)
    body = codec === 0 ? payload : await inflateRawLimited(payload, 65536, deps)
    if (body === UNSUPPORTED) return fail("unsupported-codec")
    if (body === OVERFLOW)    return fail("decompression-limit")
    if (crc32(body) !== trailer) return fail("crc-mismatch")
    return readBody(body)

const rng = mulberry32(0xC0FFEE);            // deterministic, in-repo, no dependency
for (let i = 0; i < 1000; i++) {
    const scope = pick(["SC1","SC2","SC3"], rng);
    const state = randomCanonicalState(rng);           // hits the listed boundaries
    assert(checkInvariants(state).ok);                 // the generator itself is sane
    const link = await encode(state, scope, savedAt);
    const back = await decode(link);
    assert.deepEqual(back.state, project(state, scope, savedAt));
    assert.equal(link, await encode(state, scope, savedAt));        // determinism
}

const KINDS = new Set([...8 kinds...]);
createAnnouncer(container):
    region = <div aria-live="polite" aria-atomic="true" class="visually-hidden">
    container.appendChild(region)
    let last = "";
    announce(kind, message):
        if (!KINDS.has(kind)) throw new RangeError(`unknown announce kind: ${kind}`);
        region.textContent = (message === last) ? message + "​" : message;
        last = message;

const step = {up:[-1,0], down:[1,0], left:[0,-1], right:[0,1]};
moveSelection(from, direction, modifier):
    let r = (from / 9) | 0, c = from % 9;
    if (direction === "lineStart") return modifier === "ctrl" ? 0  : r * 9;
    if (direction === "lineEnd")   return modifier === "ctrl" ? 80 : r * 9 + 8;
    const [dr, dc] = step[direction];
    const n = modifier === "ctrl" ? 3 : 1;
    r = clamp(r + dr * n, 0, 8);
    c = clamp(c + dc * n, 0, 8);
    return r * 9 + c;
// clamp, not wrap: an unreachable edge must not teleport the caret across the board

mb:micro.mb:input-type:
cellLabel(state: {
  index: number, given: number, value: number, candidates: number,
  conflict: boolean, hasNote: boolean
