mb:micro.mb:pseudocode:
cellLabel(s):
    validate(s)
    const parts = [`${((s.index/9)|0)+1}행 ${(s.index%9)+1}열`];
    if (s.given)      parts.push(`고정 숫자 ${s.given}`);
    else if (s.value) parts.push(`${s.value}`);
    else              parts.push("빈 칸");
    if (s.candidates) parts.push(`후보 ${digitsOf(s.candidates).join(", ")}`);
    if (s.conflict)   parts.push("규칙 위반");
    if (s.hasNote)    parts.push("메모 있음");
    return parts.join(", ");

updateCell(i):
    const cell = cells[i];
    cell.dataset.given    = givens[i] ? "1" : "0";
    cell.dataset.conflict = conflicts.has(i) ? "1" : "0";
    cell.dataset.note     = hasNote(i) ? "1" : "0";
    valueNode(cell).textContent = String(givens[i] || values[i] || "");
    renderCandidates(cell, candidates[i]);        // 9 fixed spans, textContent only
    cell.setAttribute("aria-label", cellLabel(snapshotOf(i)));
// never innerHTML: note text is user input and is rendered elsewhere by UI-B10,
// but the same rule is enforced here so the board can never become an injection path

const CODE_DIGIT = /^(Digit|Numpad)([1-9])$/;
resolveDigit(ev):
    const m = CODE_DIGIT.exec(ev.code);
    if (m) return Number(m[2]);
    return /^[1-9]$/.test(ev.key) ? Number(ev.key) : null;   // layout fallback

resolveAction(ev):
    if (ev.metaKey) return null;                             // never claim OS shortcuts
    if (ev.ctrlKey) return ev.code === "KeyZ" ? (ev.shiftKey ? "redo" : "undo")
                         : ev.code === "KeyY" ? "redo" : null;
    map ArrowUp/Down/Left/Right, Home, End, KeyN, KeyM, Space, F1, "?" ...

boardHasFocus(active, gridRoot):
    if (!active || active === document.body) return false;
    if (active.closest('[role="dialog"]')) return false;
    if (active.matches('textarea, input, select, [contenteditable="true"]')) return false;
    return gridRoot.contains(active) && active.getAttribute("role") === "gridcell";
// handler entry:  if (!boardHasFocus(...)) return;   // consume nothing, no preventDefault

const NAV = {moveUp:"up", moveDown:"down", moveLeft:"left", moveRight:"right",
             lineStart:"lineStart", lineEnd:"lineEnd"};
onKeyDown(ev):
    if (!boardHasFocus(...)) return;
    const action = resolveAction(ev);
    if (action in NAV) {
        const from = selection ?? 0;
        const to = moveSelection(from, NAV[action], ev.ctrlKey ? "ctrl" : "none");
        if (to !== from || selection === null) boardView.select(to);
        ev.preventDefault();                       // stop the page from scrolling
        return;
    }

const digit = resolveDigit(ev);
if (digit !== null && selection !== null) {
    const asCandidate = (ev.shiftKey && settings.shiftQuasimode) || sticky;
    const r = asCandidate ? store.toggleCandidate(selection, digit)
                          : store.setValue(selection, digit, {autoRemoveCandidates: settings.autoRemoveCandidates});
    if (!r.ok && r.reason === "given") announcer.announce("given-rejected", "고정된 칸입니다");
    ev.preventDefault();
    return;
}
if (action === "stickyToggle" && focusedRole === "gridcell") {
    sticky = !sticky;
    announcer.announce("sticky-mode", sticky ? "후보 입력 모드 켜짐" : "후보 입력 모드 꺼짐");
    ev.preventDefault();
}
if (action === "clear" && selection !== null) store.clearCell(selection);

export const KEYMAP = [                     // single source of truth, read by UI-B14 help
  {combo: "방향키",            action: "moveUp/Down/Left/Right", desc: "한 칸 이동"},
  {combo: "Ctrl+방향키",       action: "box jump",               desc: "한 박스 이동"},
  ... every row of Phase 1 section 11 ...
];
switch (action) {
  case "note":       return cb.openNote(selection);
  case "regionNote": return cb.openRegionNote(selection);
  case "notesList":  return cb.openNotesList();
  case "help":       return cb.openHelp();
  case "undo":       return applyHistory(store.undo());
  case "redo":       return applyHistory(store.redo());
}

:root { --bg-page:#F8FAFC; ... 14 properties ... }
@media (prefers-color-scheme: dark) { :root { ...same 14 names, dark values... } }
/* values are fixed by Phase 1 V4-17; changing one invalidates the 76-pair計算 */

.cell { container-type: inline-size; background: var(--bg-cell); }
.cell[data-given="1"] { background: var(--bg-cell-given); font-weight: 600; }
.cell[data-conflict="1"] { text-decoration: underline 2px; color: var(--fg-conflict); }
.candidate { font-size: 9px; font-size: max(9px, 24cqi); color: var(--fg-candidate); }
.cell[data-note="1"]::after { /* dog-ear triangle */ pointer-events: none; }

:root { --control-floor: 48px; }                    /* L3: single floor, never 44 */
.control { min-inline-size: var(--control-floor); min-block-size: var(--control-floor); }
.digit-bar button { inline-size: calc(var(--board-width) / 9); block-size: 48px; }
.digit-bar { block-size: 60px; }                    /* L2: row 60 = button 48 + pad 6*2 */
@media (min-width:1024px){...} @media (min-width:600px) and (max-width:1023px){...}
@media (max-width:599px){ .board { inline-size: calc(100vw - 16px); } }

computeGeometry(vv, fallbackHeight, boardWidth, reserved):
    const visibleTop    = vv?.offsetTop ?? 0;
    const visibleHeight = vv?.height ?? fallbackHeight;
    const available = Math.max(0, visibleHeight - reserved);
    const scale = Math.min(1, available / boardWidth);
    return {visibleTop, boardScale: Math.max(scale, MIN_SCALE)};

observe(cb): let queued = false;
    const on = () => { if (queued) return; queued = true;
                       requestAnimationFrame(() => { queued = false; cb(compute()); }); };
    vv.addEventListener("resize", on); vv.addEventListener("scroll", on);
    return () => { vv.removeEventListener(...); };

@media (prefers-reduced-motion: reduce) { * { transition-duration: 0ms !important; } }
measure at 320 / 360 / 390 CSS px: record computed candidate font-size and a
  legible / marginal / illegible judgement with the device and zoom used
if illegible at any width -> raise RK3 kill criterion, do not silently redesign

resolveVisibility(setting, coarseMatches):
    if (setting === "show") return "visible";
    if (setting === "hide") return "collapsed";
    return coarseMatches ? "visible" : "collapsed";
// the handle is rendered in both states; only the bar body collapses
render: <button class="expand-handle" aria-expanded={visible}> always present, 48x48

render: for d in 1..9 -> <button type="button" data-digit={d} aria-pressed="false">
onDigitTap(d): activeDigit = (activeDigit === d) ? null : d;
               update aria-pressed on all nine; notify board highlight
// type="button" matters: inside a form a bare <button> submits

onCellTap(index):
    if (givens[index]) { announcer.announce("given-rejected", "고정된 칸입니다"); return; }
    if (activeDigit === null) { boardView.select(index); return; }      // Cell First
    return sticky ? store.toggleCandidate(index, activeDigit)
                  : store.setValue(index, activeDigit,
                                   {autoRemoveCandidates: settings.autoRemoveCandidates});

onPencilTap():
    sticky = !sticky;
    pencilBtn.setAttribute("aria-pressed", String(sticky));
    boardRoot.dataset.candidateMode = sticky ? "1" : "0";   // dashed outline via CSS
    badge.hidden = !sticky;                                  // text badge, not colour
    announcer.announce("sticky-mode", sticky ? "후보 입력 모드 켜짐" : "후보 입력 모드 꺼짐");

onPointerDown(index): timer = setTimeout(() => { fired = true;
    navigator.vibrate?.(10); cb.openNoteEditor({kind:"cell", key:index}); }, 400);
onPointerMove(e): if (moved beyond slop) clearTimeout(timer);   // it was a scroll
onPointerUp(): clearTimeout(timer); if (!fired) onCellTap(index); fired = false;
onMemoTap(): selection === null ? cb.openNotesList() : cb.openNoteEditor(currentTarget);

