def workload(dim, trials, seed):
    if trials < 1: raise ValueError(f"trials must be >= 1, got {trials}")
    spec = spec_for(dim)                       # raises for unsupported dims
    rng = random.Random(seed)                  # local rng, never random.seed()
    return [generator.generate_puzzle(dim=spec, rng=rng) for _ in range(trials)]

def ab_timing(dims=(9, 12, 16), trials=10, seed=7):
    for dim in dims:
        rng_free_times = []
        for i in range(trials):
            t0 = perf_counter(); workload(dim, 1, seed + i); rng_free_times.append(perf_counter() - t0)
        print(dim, trials, seed, median(rng_free_times), max(rng_free_times))

