    call_counts(); profile_section(); ab_timing()                              # new

def contradiction_proven(board, index, value, spec, max_depth=1):
    validate(board, index, value, spec)
    work = list(board); work[index] = value
    for _ in range(max_depth):
        singles = []
        for i, cell in enumerate(work):
            if cell: continue
            allowed = [v for v in range(1, spec.dim + 1)
                       if not spec.peers_forbid(work, i, v)]
            if not allowed:
                return True                 # proven: a cell has no candidate left
            if len(allowed) == 1:
                singles.append((i, allowed[0]))
        if not singles:
            return False                    # nothing more to deduce, stay conservative
        for i, v in singles:
            if spec.peers_forbid(work, i, v):
                return True                 # two singles collided
            work[i] = v
    return False

