mb:micro.mb:pseudocode:
# game/sudoku/d1_client.py
class D1Client:
    def __init__(self, account_id, database_id, api_token, http=None):
        self._url = (f"https://api.cloudflare.com/client/v4/accounts/{account_id}"
                     f"/d1/database/{database_id}/query")
        self._headers = {"Authorization": f"Bearer {api_token}"}
        self._http = http or requests.Session()
        self._last_changes = 0

    def query(self, sql, params=()):
        resp = self._http.post(self._url, json={"sql": sql, "params": list(params)},
                                headers=self._headers, timeout=10)
        resp.raise_for_status()
        result = resp.json()["result"][0]
        self._last_changes = result["meta"]["changes"]
        return result["results"]

    @property
    def last_changes(self): return self._last_changes

def d1_client_from_env(http=None):
    missing = [k for k in ("CLOUDFLARE_ACCOUNT_ID", "CLOUDFLARE_D1_DATABASE_ID",
                          "CLOUDFLARE_API_TOKEN") if not os.environ.get(k)]
    if missing: raise RuntimeError(f"missing D1 credentials: {missing}")
    return D1Client(os.environ["CLOUDFLARE_ACCOUNT_ID"],
                    os.environ["CLOUDFLARE_D1_DATABASE_ID"],
                    os.environ["CLOUDFLARE_API_TOKEN"], http=http)

# game/management/commands/init_d1_schema.py
d1_client_from_env().query(SCHEMA)

