        raise CommandError("generated puzzle length mismatch")
    rows.append((dim, difficulty, givens_s, solution_s, timezone.now().isoformat()))
    if (i + 1) % 10 == 0: self.stdout.write(f"{i+1}/{count}")
d1_client_from_env().batch_insert("puzzles",
