def new_puzzle(request):
    row = _take_cached(dim=9, difficulty="medium")
    if row is not None:
        return JsonResponse({"puzzle": _to_ints(row["givens"]),
                             "solution": _to_ints(row["solution"])})
    puzzle, solution = generator.generate_puzzle()          # unchanged fallback
    return JsonResponse({"puzzle": puzzle, "solution": solution})

def _take_cached(dim, difficulty):
    try:
        client = d1_client_from_env()
        rows = client.query(
            "SELECT id, givens, solution FROM puzzles "
            "WHERE dim=? AND difficulty=? AND consumed=0 LIMIT 1", (dim, difficulty))
    except (RuntimeError, requests.RequestException):
        return None                                          # auth/network failure -> fall back
    if not rows: return None
    row = rows[0]
    client.query("UPDATE puzzles SET consumed=1 WHERE id=? AND consumed=0", (row["id"],))
    return row if client.last_changes == 1 else None          # lost the race, fall back

